import { useMemo } from 'react';
// prettier-ignore
const buildNodeMap = ({
  nodes,
  nodeMap,
  parent
}) => {
  if (!nodes || nodes.length < 1) {
    return nodeMap;
  }
  return nodes.reduce((acc, node) => {
    acc.set(node.id, {
      children: node.children?.map(child => child.id) ?? [],
      id: node.id,
      parent
    });
    if (node.children && node.children.length > 0) {
      return buildNodeMap({
        nodes: node.children,
        nodeMap: acc,
        parent: node.id
      });
    }
    return acc;
  }, nodeMap);
};

// prettier-ignore
export const useNodeMap = ({
  nodes
}) => {
  return useMemo(() => buildNodeMap({
    nodes,
    nodeMap: new Map()
  }), [nodes]);
};